def repeatedPathCoefficients (b : Basis (Fin N) 𝕜 E) (m : ℕ) (hN : 0 < N) :
    E →ₗ[𝕜] (Fin (m * N) → 𝕜) :=
  LinearMap.pi fun i => (↑(1 / m : ℝ) : 𝕜) • b.coord (periodicFinIndex hN i.val)

