def repeatedPathLinearMap (b : Basis (Fin N) 𝕜 E) (m : ℕ) (hN : 0 < N) :
    E →ₗ[𝕜] (Fin (m * N + 1) → E) :=
  (finitePrefixPath (repeatedPathVectors b m hN)).comp (repeatedPathCoefficients b m hN)

